const action = (params.action || 'now').toLowerCase();
const tz = params.timezone || 'UTC';
function fmt(d, t = tz) {
  try { return d.toLocaleString('sv-SE', { timeZone: t, hour12: false }) + ' ' + t; }
  catch { return d.toISOString(); }
}
if (action === 'now') {
  const d = new Date();
  return { iso: d.toISOString(), unix: Math.floor(d.getTime() / 1000), formatted: fmt(d), timezone: tz };
}
if (action === 'parse') {
  const input = params.input;
  if (!input) throw new Error('params.input required');
  const d = new Date(input);
  if (isNaN(d.getTime())) throw new Error('Failed to parse: ' + input);
  return { input, iso: d.toISOString(), unix: Math.floor(d.getTime() / 1000), formatted: fmt(d), weekday: d.toLocaleDateString('en-US', { weekday: 'long' }) };
}
if (action === 'format') {
  const input = params.input;
  if (input === undefined) throw new Error('params.input required');
  const d = typeof input === 'number' ? new Date(input * 1000) : new Date(input);
  if (isNaN(d.getTime())) throw new Error('Invalid input');
  return { iso: d.toISOString(), formatted: fmt(d), timezone: tz };
}
if (action === 'diff') {
  const a = new Date(params.from);
  const b = new Date(params.to || Date.now());
  if (isNaN(a.getTime()) || isNaN(b.getTime())) throw new Error('params.from / params.to invalid');
  const ms = b.getTime() - a.getTime();
  return { from: a.toISOString(), to: b.toISOString(), ms, seconds: Math.floor(ms / 1000), minutes: Math.floor(ms / 60000), hours: (ms / 3600000).toFixed(2), days: (ms / 86400000).toFixed(2) };
}
if (action === 'add') {
  const d = params.input ? new Date(params.input) : new Date();
  if (isNaN(d.getTime())) throw new Error('params.input invalid');
  d.setDate(d.getDate() + Number(params.days || 0));
  d.setHours(d.getHours() + Number(params.hours || 0));
  d.setMinutes(d.getMinutes() + Number(params.minutes || 0));
  d.setSeconds(d.getSeconds() + Number(params.seconds || 0));
  return { iso: d.toISOString(), formatted: fmt(d), timezone: tz };
}
throw new Error('Unknown action: ' + action);
